-- description: Add tenant-scoped typed Agent memory references
-- rollback: Export active memory references before dropping the additive table
-- minimum-app-version: 0.1.0
CREATE TABLE agents.memory_refs(id text PRIMARY KEY,organization_id text NOT NULL,project_id text NOT NULL,agent_key text NOT NULL,type text NOT NULL CHECK(type IN('evidence','artifact','recommendation','task_summary')),reference_id text NOT NULL,provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object'),retention_days integer NOT NULL CHECK(retention_days BETWEEN 1 AND 3650),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(organization_id,project_id,agent_key,type,reference_id),FOREIGN KEY(organization_id,project_id)REFERENCES project_governance.projects(organization_id,id)ON DELETE CASCADE);CREATE INDEX agent_memory_scope_idx ON agents.memory_refs(organization_id,project_id,agent_key,expires_at);DO $p$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='oneshowseo_app')THEN GRANT SELECT,INSERT,UPDATE ON agents.memory_refs TO oneshowseo_app;END IF;IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='oneshowseo_worker')THEN GRANT SELECT,INSERT ON agents.memory_refs TO oneshowseo_worker;END IF;END $p$;
